284	    /**
285	     * The owner's salutation, derived at read time as the {@link #getTitle() title}, a single space
286	     * and the {@link #getLastName() lastName} (e.g. {@code 'DR Franklin'}); just the lastName when no
287	     * title is present.
288	     */
289	    @Transient
290	    public String getSalutation() {
291	        if (this.title == null || this.title.isBlank()) {
292	            return this.getLastName();
293	        }
294	        return this.title + " " + this.getLastName();
295	    }
296	
297	    /**
298	     * The canonical relative URL of this owner, derived at read time as {@code '/api/owners/'}
299	     * followed by the owner's {@link #getId() id}.
300	     */
301	    @Transient
302	    public String getSelfLink() {
303	        return "/api/owners/" + this.getId();
304	    }
305	
306	    /**
307	     * The fiscal year (starting 1 July) containing {@code date}, named by the calendar year it ends
308	     * in: a date on or after 1 July belongs to the next calendar year's fiscal year (e.g. 14 Aug
309	     * 2026 is fiscal year 2027), a date before 1 July to the current calendar year's.
310	     */
311	    public static int fiscalYearOf(LocalDate date) {
312	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
313	    }
314	
315	    /**
316	     * The owner's fiscal year, derived at read time from the business-day-adjusted
317	     * {@link #getRegistrationDate() registrationDate} and formatted {@code 'FY<YY>'} where YY is the
318	     * last two digits of the fiscal year (which starts on 1 July; e.g. a registration date of
319	     * 14 Aug 2026 yields {@code 'FY27'}). {@code null} when the owner has no registrationDate.
320	     */
321	    @Transient
322	    public String getFiscalYear() {
323	        if (this.registrationDate == null) {
324	            return null;
325	        }
326	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
327	    }
328	
329	    /**
330	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
331	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
332	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure — the
333	     * number of elapsed fiscal years since {@link #getRegistrationDate() registrationDate}
334	     * ({@link #getFiscalYear() fiscal year} basis, 1 July start) — is one or more. A newly created
335	     * owner has zero elapsed fiscal years of tenure, so a new owner can score at most 5 points.
336	     */
337	    @Transient
338	    public Integer getMembershipPoints() {
339	        return computeMembershipPoints(this.householdSize);
340	    }
341	
342	    private int computeMembershipPoints(Integer householdSize) {
343	        int points = 0;
344	        boolean hasEmail = this.email != null && !this.email.isBlank();
345	        if (hasEmail) {
346	            points += 2;
347	        }
348	        if (this.namesakeCount != null && this.namesakeCount == 0) {
349	            points += 1;
350	        }
351	        if (householdSize != null && householdSize >= 3) {
352	            points += 2;
353	        }
354	        if (this.registrationDate != null
355	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
356	            points += 3;
357	        }
358	        return points;
359	    }
360	
361	    /**
362	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
363	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
364	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
365	     *
366	     * <p>A new owner also cannot outrank their household: when a {@link #getMembershipLevelCap()
367	     * membershipLevelCap} is set (one above the highest level in the household at the moment the owner
368	     * joined) the banded level is capped to it.
369	     */
370	    @Transient
371	    public Integer getMembershipLevel() {
372	        return capLevel(levelForPoints(getMembershipPoints()));
373	    }
374	
375	    /**
376	     * The membership level this owner would band to if their household held {@code householdSize}
377	     * members, still honouring this owner's own {@link #getMembershipLevelCap() cap}. Used when a
378	     * new member sizes their household ceiling against the household as it stands once they join, so
379	     * every existing member is scored under the same (grown) household size.
380	     */
381	    public int membershipLevelForHouseholdSize(int householdSize) {
382	        return capLevel(levelForPoints(computeMembershipPoints(householdSize)));
383	    }
384	
385	    private int capLevel(int level) {
386	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
387	            return this.membershipLevelCap;
388	        }
389	        return level;
390	    }
391	
392	    private static int levelForPoints(int points) {
393	        if (points <= 1) {
394	            return 1;
395	        }
396	        if (points <= 3) {
397	            return 2;
398	        }
399	        if (points <= 5) {
400	            return 3;
401	        }
402	        return 4;
403	    }
404	
405	    /**
406	     * The owner's segment, derived at read time and formatted {@code '<TIER>_<AREA>'} — one of
407	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
408	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()
409	     * membershipLevel} is 3 or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the
410	     * {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
411	     * {@code 'REGIONAL'}.
412	     */
413	    @Transient
414	    public String getOwnerSegment() {
415	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
416	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
417	        return tier + "_" + area;
418	    }
419	
420	    /**
421	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
422	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
423	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
424	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
425	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
426	     * yields {@code 'UNKNOWN'}.
427	     */
428	    @Transient
429	    public String getLocality() {
430	        String byPostcode = regionForPostcode(this.postcode);
431	        if (byPostcode != null) {
432	            return byPostcode;
433	        }
434	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
435	    }
436	
437	    /**
438	     * The owner's IANA timezone, derived at read time from the owner's region
439	     * ({@link #getLocality()}) via the pinned region-to-timezone table (NSW->Australia/Sydney,
440	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). {@code null} when the region is unknown.
441	     */
442	    @Transient
443	    public String getTimezone() {
444	        return REGION_TIMEZONE.get(getLocality());
445	    }
446	
447	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
448	    private static String regionForPostcode(String postcode) {
449	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
450	            return null;
451	        }
452	        int value = Integer.parseInt(postcode);
453	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
454	            int[] range = entry.getValue();
455	            if (value >= range[0] && value <= range[1]) {
456	                return entry.getKey();
457	            }
458	        }
459	        return null;
460	    }
461	
462	    /**
463	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
464	     * time: the country code, a space, then the national digits grouped in threes (e.g.
465	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
466	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
467	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
468	     * has no telephone or it is not a well-formed E.164 number.
469	     */
470	    @Transient
471	    public String getTelephoneDisplay() {
472	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
473	            return null;
474	        }
475	        String digits = this.telephone.substring(1); // drop the leading '+'
476	        String countryCode = countryCodeOf(digits);
477	        String national = digits.substring(countryCode.length());
478	        StringBuilder display = new StringBuilder("+").append(countryCode);
479	        display.append(' ');
480	        for (int i = 0; i < national.length(); i++) {
481	            if (i > 0 && i % 3 == 0) {
482	                display.append(' ');
483	            }
484	            display.append(national.charAt(i));
485	        }
486	        return display.toString();
487	    }
488	
489	    /**
490	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
491	     * are matched longest-first; any other number falls back to a two-digit country code.
492	     */
493	    private static String countryCodeOf(String digits) {
494	        for (String code : KNOWN_COUNTRY_CODES) {
495	            if (digits.startsWith(code) && digits.length() > code.length()) {
496	                return code;
497	            }
498	        }
499	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
500	    }
501	
502	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
503	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
504	
505	    /**
506	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
507	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
508	     */
509	    @Transient
510	    public String getContactPreference() {
511	        boolean hasEmail = this.email != null && !this.email.isBlank();
512	        return hasEmail ? "EMAIL" : "PHONE";
513	    }
514	
515	    /**
516	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
517	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
518	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
519	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
520	     */
521	    @Transient
522	    public String getAgeBand() {
523	        if (this.birthDate == null || this.registrationDate == null) {
524	            return null;
525	        }
526	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
527	        if (years < 18) {
528	            return "MINOR";
529	        }
530	        if (years < 65) {
531	            return "ADULT";
532	        }
533	        return "SENIOR";
534	    }
535	
536	    /**
537	     * The single derived duplicate-detection key: the 64-character lower-case hex SHA-256 of
538	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (the normalized
539	     * telephone, the lower-cased email or empty when absent, and the {@link Soundex} of the
540	     * lastName). All duplicate detection is expressed through this one key: a create whose WHOLE
541	     * identityKey equals an existing owner's is a duplicate. Because the telephone is part of the
542	     * key, two members of the same household with different telephones have different identityKeys
543	     * and are both allowed.
544	     */
545	    @Transient
546	    public String getIdentityKey() {
547	        return identityKey(this.telephone, this.email, this.lastName);
548	    }
549	
550	    /**
551	     * Derive the {@link #getIdentityKey() identityKey} from the raw parts, so a create pipeline can
552	     * compute the key for an incoming request exactly as a stored owner reports it.
553	     */
554	    public static String identityKey(String telephone, String email, String lastName) {
555	        String tel = telephone == null ? "" : telephone;
556	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
557	        return sha256Hex(tel + "|" + mail + "|" + Soundex.encode(lastName));
558	    }
559	
560	    /** The 64-character lower-case hex SHA-256 of {@code seed}. */
561	    private static String sha256Hex(String seed) {
562	        try {
563	            java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
564	            byte[] hash = digest.digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
565	            StringBuilder hex = new StringBuilder(64);
566	            for (byte b : hash) {
567	                hex.append(String.format("%02x", b & 0xff));
568	            }
569	            return hex.toString();
570	        } catch (java.security.NoSuchAlgorithmException e) {
571	            throw new IllegalStateException("SHA-256 not available", e); // every JRE ships SHA-256
572	        }
573	    }
574	
575	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
576	    private static final Map<String, String> CITY_REGION =
577	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
578	
579	    /** Region -> IANA timezone for {@link #getTimezone()}. */
580	    private static final Map<String, String> REGION_TIMEZONE =
581	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
582	
583	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
584	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
585	        "NSW", new int[] {2000, 2099},
586	        "VIC", new int[] {3000, 3099},
587	        "QLD", new int[] {4000, 4099});
588	
589	    protected Set<Pet> getPetsInternal() {
590	        if (this.pets == null) {
591	            this.pets = new HashSet<>();
592	        }
593	        return this.pets;
594	    }
595	
596	    protected void setPetsInternal(Set<Pet> pets) {
597	        this.pets = pets;
598	    }
599	
600	    public List<Pet> getPets() {
601	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
602	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
603	        return Collections.unmodifiableList(sortedPets);
604	    }
605	
606	    public void setPets(List<Pet> pets) {
607	        this.pets = new HashSet<>(pets);
608	    }
609	
610	    public void addPet(Pet pet) {
611	        getPetsInternal().add(pet);
612	        pet.setOwner(this);
613	    }
614	
615	    /**
616	     * Return the Pet with the given name, or null if none found for this Owner.
617	     *
618	     * @param name to test
619	     * @return true if pet name is already in use
620	     */
621	    public Pet getPet(String name) {
622	        return getPet(name, false);
623	    }
624	
625	    /**
626	     * Return the Pet with the given name, or null if none found for this Owner.
627	     *
628	     * @param name to test
629	     * @return true if pet name is already in use
630	     */
631	    public Pet getPet(String name, boolean ignoreNew) {
632	        name = name.toLowerCase();
633	        for (Pet pet : getPetsInternal()) {
634	            if (!ignoreNew || !pet.isNew()) {
635	                String compName = pet.getName();
636	                compName = compName.toLowerCase();
637	                if (compName.equals(name)) {
638	                    return pet;
639	                }
640	            }
641	        }
642	        return null;
643	    }
644	
645	    public Pet getPet(Integer petId) {
646	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
647	    }
648	
649	    @Override
650	    public String toString() {
651	        return new ToStringCreator(this)
652	
653	            .append("id", this.getId())
654	            .append("new", this.isNew())
655	            .append("lastName", this.getLastName())
656	            .append("firstName", this.getFirstName())
657	            .append("address", this.address)
658	            .append("city", this.city)
659	            .append("telephone", this.telephone)
660	            .toString();
661	    }
662	}
